def algorithm(func, dim, lb, ub, budget, rng):
    if not isinstance(rng, np.random.RandomState):
        rng = np.random.default_rng(rng)

    x_best = np.array([0.] * dim)
    f_best = func(x_best)

    for _ in range(budget):
        for i in range(dim):
            x_candidate = x_best.copy()
            delta = rng.uniform(-5.0, 5.0)
            x_candidate[i] += delta
            x_candidate = np.clip(x_candidate, lb, ub)
            f_candidate = func(x_candidate)

            if f_candidate < f_best:
                x_best = x_candidate
                f_best = f_candidate

    return x_best

def algorithm(func, dim, lb, ub, budget, rng):
    best_x = np.zeros(dim)
    best_y = float('inf')
    for _ in range(budget):
        x = rng.uniform(lb, ub, size=dim)
        y = func(x)
        if y < best_y:
            best_y = y
            best_x = x
    return best_x
